class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def addLists(a, b):
    sa = list(a)
    sb = list(b)
    head = None
    carry = 0
    while sa or sb or carry:
        total = carry
        if sa:
            total += sa.pop()
        if sb:
            total += sb.pop()
        head = ListNode(total % 10, head)
        carry = total // 10
    return dump(head)
